// =============================================================================
// Node 2: Webhook Secret & Security Verification
// =============================================================================
const headers = $input.first().json.headers || {};
const configuredSecret = $env.BRIK_WEBHOOK_SECRET || 'brik_sec_default_2026';
const incomingSecret = headers['x-brik-webhook-secret'] || headers['x-webhook-secret'] || '';

// If secret is set in env, enforce it; otherwise allow for initial test setup
let isAuthorized = true;
let authMessage = 'Authorized';

if ($env.BRIK_WEBHOOK_SECRET && incomingSecret !== configuredSecret) {
  isAuthorized = false;
  authMessage = 'Unauthorized: Invalid X-Brik-Webhook-Secret header.';
}

return [{
  json: {
    ...$input.first().json,
    _security: {
      authorized: isAuthorized,
      message: authMessage
    }
  }
}];

// =============================================================================
// Node 3: Payload Validation & Multi-Tenant Normalization
// =============================================================================
const rawData = $input.first().json.body || $input.first().json.record || $input.first().json;

// 1. Extract Lead ID & Organization ID (Multi-Tenant Identifier)
const leadId = rawData.lead_id || rawData.id || '';
const orgId = rawData.organization_id || rawData.client_id || '';
const orgName = rawData.organization_name || 'Brik Client';

// 2. Extract Lead Contact Details
const firstName = (rawData.first_name || '').trim();
const lastName = (rawData.last_name || '').trim();
const fullName = (rawData.name || `${firstName} ${lastName}`).trim() || 'New Lead';
const email = (rawData.email || '').trim();
const phone = (rawData.phone || '').trim();
const serviceRequested = (rawData.service_requested || rawData.service || 'General Service').trim();
const source = (rawData.source || 'Website Lead Form').trim();
const status = (rawData.status || 'New').trim();
const notes = (rawData.notes || '').trim();
const createdAt = rawData.created_at || new Date().toISOString();

// 3. Validation Rules
const errors = [];
if (!leadId) errors.push('Missing required field: lead_id / id');
if (!orgId) errors.push('Missing required field: organization_id / client_id');
if (!fullName && !email && !phone) errors.push('Missing contact information: name, email, or phone required');

const isValid = errors.length === 0;

return [{
  json: {
    is_valid: isValid,
    validation_errors: errors,
    lead: {
      lead_id: leadId,
      organization_id: orgId,
      organization_name: orgName,
      first_name: firstName || fullName.split(' ')[0] || '',
      last_name: lastName || fullName.split(' ').slice(1).join(' ') || '',
      name: fullName,
      email: email || null,
      phone: phone || null,
      service_requested: serviceRequested,
      source: source,
      status: status,
      notes: notes || null,
      created_at: createdAt
    }
  }
}];

// =============================================================================
// Node 5: Idempotency & Deduplication Check
// Prevents duplicate processing from page reloads or retries using lead_id
// =============================================================================
const staticData = $getWorkflowStaticData('global');
staticData.processedLeadIds = staticData.processedLeadIds || [];

const currentLead = $input.first().json.lead;
const leadId = currentLead.lead_id;

let isDuplicate = false;

if (staticData.processedLeadIds.includes(leadId)) {
  isDuplicate = true;
  console.log(`[DEDUPLICATION] Lead ID ${leadId} was already processed. Skipping duplicate action.`);
} else {
  // Store the processed lead ID (capped at last 5000 IDs)
  staticData.processedLeadIds.push(leadId);
  if (staticData.processedLeadIds.length > 5000) {
    staticData.processedLeadIds.shift();
  }
}

return [{
  json: {
    ...$input.first().json,
    is_duplicate: isDuplicate,
    idempotency_key: leadId
  }
}];

// =============================================================================
// Node 6: Multi-Tenant Audit Logger & Lead Confirmation
// Logs client details and readies downstream automation for Part 5 (Twilio)
// =============================================================================
const lead = $input.first().json.lead;
const isDuplicate = $input.first().json.is_duplicate;

const logMessage = `[BRIK LEAD INGESTION] Multi-Tenant Org: ${lead.organization_id} (${lead.organization_name}) | Lead: "${lead.name}" | Service: "${lead.service_requested}" | Phone: ${lead.phone || 'N/A'} | Status: ${lead.status}`;

console.log(logMessage);

return [{
  json: {
    success: true,
    lead_id: lead.lead_id,
    organization_id: lead.organization_id,
    organization_name: lead.organization_name,
    name: lead.name,
    phone: lead.phone,
    email: lead.email,
    service: lead.service_requested,
    status: lead.status,
    is_duplicate: isDuplicate,
    message: isDuplicate ? 'Lead already ingested (idempotent duplicate skipped)' : 'Lead ingested successfully into n8n workflow'
  }
}];

